extra_css:
/* Reference canvas only: replace tokens with the approved project design. */
.doc-slide { box-sizing:border-box; position:relative; width:1280px; height:720px; overflow:hidden; background:#fff; color:#17212b; font-family:"Malgun Gothic","Noto Sans KR",sans-serif; padding:56px; }
.doc-slide * { box-sizing:border-box; }
.doc-slide h1 { font-size:40px; line-height:1.25; margin:0 0 28px; }
.doc-slide h2 { font-size:28px; line-height:1.3; margin:0 0 20px; }
.doc-slide p, .doc-slide li { font-size:24px; line-height:1.5; margin:0 0 18px; }
.doc-slide .foot { position:absolute; bottom:28px; left:56px; right:56px; font-size:16px; }
.doc-slide .split { display:grid; grid-template-columns: 3fr 2fr; gap:56px; }
.doc-slide .row { display:grid; grid-template-columns:1fr 1fr 1fr; gap:40px; }
.doc-slide .rail { border-left:3px solid #17212b; padding-left:28px; }
.doc-slide .wide { max-width:960px; }
